insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('niacinamide', 'Niacinamide', 'Niacinamide', 'Vitamin / active ingredient', 'full', 'A water-soluble form of vitamin B3 used in skincare. It helps support the skin barrier, may reduce the look of excess oil and can help with uneven tone over several weeks of use.', array['Skin conditioning', 'Barrier support', 'Oil (sebum) regulation', 'Tone evening']::text[], array['Serums', 'Moisturisers', 'Toners', 'Sunscreens']::text[], 'moderate', 'Several controlled studies support topical niacinamide for barrier function, sebum and uneven pigmentation, mostly at 2–5%. Results are gradual and modest; higher percentages are not proven to work better.', 'Most published studies used about 2–5%. Products marketed at 10% or more exist, but higher strengths are not shown to be more effective and may irritate some people.', null, '{}'::text[], '{"benefits":["Supports the skin barrier and may reduce water loss","May reduce the appearance of oiliness and enlarged-looking pores","May help fade uneven tone and post-acne marks with consistent use","Generally well tolerated by most skin types"],"limitations":["Effects are gradual — usually assessed after 4–12 weeks","Not a treatment for moderate or severe acne on its own","Higher percentages are a marketing differentiator more than an evidence-based one"],"adverseEffects":["Mild redness, stinging or itching in some people, more often at high concentrations"],"precautions":["Patch test a new product, especially high-strength serums","If you have very sensitive skin, start with lower strengths (around 2–5%)"],"compatibility":["Generally used alongside sunscreen, moisturisers, retinoids and acids","The older idea that niacinamide must never be used with vitamin C comes from conditions (heat, long storage) not typical of normal use; if a combination stings, separate them (morning/evening)"],"applications":{"skin":"Serums, moisturisers and some sunscreens for oiliness, barrier support and uneven tone."},"forms":[{"name":"Niacinamide (nicotinamide)","note":"The form used in skincare."},{"name":"Niacin (nicotinic acid)","note":"A different form of vitamin B3 that can cause flushing; not the same as niacinamide in skincare."}],"misconceptions":[{"myth":"Higher percentage means better results.","fact":"Most evidence is at 2–5%. Higher strengths are not proven better and can irritate."},{"myth":"Niacinamide cannot be used with vitamin C.","fact":"This concern is based on conditions not typical of normal use. Separate them only if your skin reacts."}],"faqs":[{"q":"Is niacinamide good for oily skin?","a":"It is commonly used for oily and acne-prone skin and studies suggest it may reduce the look of oiliness. It works gradually and is not a substitute for acne treatment when acne is moderate or severe."},{"q":"Can I use it every day?","a":"Most products are designed for once- or twice-daily use. Follow the label and reduce frequency if irritation occurs."}]}'::jsonb, '{"what":{"summary":"A form of vitamin B3 used in skincare and some haircare products.","points":["Water-soluble and stable in most formulas","Found in serums, moisturisers, toners and sunscreens"]},"why":{"summary":"Used to support the skin barrier, regulate the look of oil and even out tone.","points":["Not essential for everyone — useful when these goals matter to you","Evidence: moderate, mostly at 2–5%"]},"when":{"summary":"Morning or evening, once or twice daily depending on the product.","points":["Results are usually judged after 4–12 weeks","Pause if you notice persistent stinging or redness"]},"who":{"summary":"Most skin types, especially oily, combination and acne-prone skin.","points":["Sensitive skin: start with lower strengths","Not a replacement for medical acne treatment"]},"where":{"summary":"Face and neck; sometimes body products.","points":["Avoid the eye area unless the product is made for it","Do not apply to broken or freshly shaved skin if it stings"]},"how":{"summary":"Apply a few drops (or a thin layer) to clean skin before moisturiser; use sunscreen in the day.","points":["Start slowly with high-strength serums","Common mistake: layering several niacinamide products and getting irritation"]}}'::jsonb, '{"skinTypes":["oily","combination","normal","dry"],"skinConcerns":["acne","uneven_tone","texture"],"climates":["hot_humid","monsoon","moderate"]}'::jsonb, 'published', '2026-10-12');
