insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('salicylic-acid', 'Salicylic Acid', 'Salicylic Acid', 'Exfoliant / acne active (BHA)', 'full', 'An oil-soluble beta hydroxy acid that loosens dead skin cells, including inside pores. Widely used for blackheads, whiteheads and mild acne, and in some scalp products for flaking.', array['Exfoliation inside pores', 'Acne treatment (OTC)', 'Keratolytic']::text[], array['Cleansers', 'Toners', 'Serums', 'Spot treatments', 'Anti-dandruff shampoos']::text[], 'established', 'Recognised by regulators (e.g. US FDA acne monograph) as an OTC acne active at 0.5–2%. Effective mainly for mild comedonal acne; less effective than prescription options for inflammatory acne.', 'Over-the-counter acne products: 0.5–2% (US FDA acne monograph). Higher strengths are used in professional peels and some scalp/keratolytic products.', null, array['potential_irritant', 'drying', 'pregnancy_caution']::text[], '{"benefits":["Helps clear blocked pores (blackheads and whiteheads)","Recognised over-the-counter acne active in several regulatory systems","Helps loosen scale on the scalp in some dandruff products"],"limitations":["Modest effect on inflamed (red, painful) acne","Does not prevent acne scarring on its own","Wash-off cleansers have short contact time"],"adverseEffects":["Dryness, peeling, stinging","Irritation when combined with other exfoliants or retinoids"],"precautions":["Avoid if you are allergic to aspirin (salicylates)","If pregnant or breastfeeding, ask a doctor before regular leave-on use over large areas","Use sunscreen; exfoliated skin can be more sun-sensitive","Not for use on broken or eczematous skin"],"compatibility":["Use with care alongside retinoids, benzoyl peroxide or AHAs — introduce one at a time","Pairs well with non-comedogenic moisturisers to reduce dryness"],"applications":{"skin":"Cleansers, toners and leave-on serums for blackheads and mild acne.","hair":"Some anti-dandruff and scalp-scale shampoos."},"forms":[{"name":"Salicylic acid","note":"The active acid."},{"name":"Betaine salicylate / willow bark extract","note":"Marketed as gentler alternatives; evidence is far weaker than for salicylic acid itself."}],"misconceptions":[{"myth":"More frequent use clears acne faster.","fact":"Over-use causes dryness and irritation, which can make skin look worse."}],"faqs":[{"q":"Can I use salicylic acid daily?","a":"Many cleansers are designed for daily use. For leave-on products, start a few times a week and increase only if tolerated."}]}'::jsonb, '{"what":{"summary":"An oil-soluble exfoliating acid (BHA) that works inside pores."},"why":{"summary":"To help clear blackheads, whiteheads and mild acne, or loosen scalp flakes.","points":["Established OTC acne active at 0.5–2%","Not necessary if you do not have clogged pores or acne"]},"when":{"summary":"Usually once daily or a few times a week; often in the evening.","points":["Reduce use if skin becomes dry or flaky","Avoid on sunburnt or broken skin"]},"who":{"summary":"Oily, combination and acne-prone skin; scalp flaking.","points":["Caution: aspirin allergy, very dry or sensitive skin, pregnancy (ask a doctor)"]},"where":{"summary":"Face, chest, back or scalp where needed.","points":["Avoid eyes, lips and inside the nose"]},"how":{"summary":"Apply a thin layer or use as a cleanser, then moisturise. Use sunscreen in the day.","points":["Introduce one exfoliating active at a time","Common mistake: combining several acids and scrubs at once"]}}'::jsonb, '{"skinTypes":["oily","combination"],"skinConcerns":["acne","texture"],"hairConcerns":["dandruff"],"cautionFor":["sensitive_skin","pregnancy"],"climates":["hot_humid","monsoon"]}'::jsonb, 'published', '2026-10-12');
