insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('hyaluronic-acid', 'Hyaluronic Acid', 'Sodium Hyaluronate / Hyaluronic Acid', 'Humectant', 'full', 'A humectant that binds water and helps the surface of the skin feel hydrated and plump. Usually listed as sodium hyaluronate.', array['Humectant (draws water into the upper skin)', 'Skin conditioning']::text[], array['Serums', 'Moisturisers', 'Sheet masks', 'Gels']::text[], 'moderate', 'Topical hyaluronic acid improves skin hydration in short-term studies. Claims about deep "anti-ageing" or filling wrinkles from creams are not supported — injectable fillers are a different product.', null, null, '{}'::text[], '{"benefits":["Improves surface hydration and softness","Lightweight feel suits humid weather","Very well tolerated"],"limitations":["Effects are temporary and surface-level","Does not repair the barrier like ceramides or occlusives","Claims based on \"molecular weights\" are mostly marketing"],"adverseEffects":["Rare irritation; usually due to other ingredients in the formula"],"precautions":["In very dry air, follow with a moisturiser to reduce water loss"],"compatibility":["Compatible with almost all routines"],"applications":{"skin":"Hydrating serums, gels and moisturisers."},"forms":[{"name":"Sodium hyaluronate","note":"Salt form; the most common label name."},{"name":"Hydrolysed hyaluronic acid","note":"Smaller fragments; marketed as penetrating deeper. Clinical differences are not well established."}],"misconceptions":[{"myth":"Hyaluronic acid \"holds 1000 times its weight in water\", so creams fill wrinkles.","fact":"Topical HA hydrates the surface temporarily; it does not work like injected fillers."}]}'::jsonb, '{"what":{"summary":"A water-binding humectant, usually listed as sodium hyaluronate."},"why":{"summary":"To make skin feel more hydrated and comfortable.","points":["Optional — glycerin does a similar job at lower cost"]},"when":{"summary":"Morning and/or evening."},"who":{"summary":"All skin types, including sensitive skin."},"where":{"summary":"Face, neck and body."},"how":{"summary":"Apply to slightly damp skin, then follow with moisturiser in dry conditions.","points":["Common mistake: using HA alone in very dry, air-conditioned rooms"]}}'::jsonb, '{"skinTypes":["oily","dry","combination","normal","sensitive"],"skinConcerns":["dryness"]}'::jsonb, 'published', '2026-10-10');
