insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('glycerin', 'Glycerin', 'Glycerin', 'Humectant', 'full', 'One of the most widely used and best-studied humectants. Draws water into the skin and supports barrier function. Also used in toothpastes for texture.', array['Humectant', 'Skin protecting', 'Solvent']::text[], array['Moisturisers', 'Cleansers', 'Toothpastes', 'Soaps', 'Serums']::text[], 'established', 'Glycerin is among the most studied moisturising ingredients and is a standard component of moisturisers.', null, null, '{}'::text[], '{"benefits":["Improves hydration and skin softness","Supports barrier function","Inexpensive and very well tolerated"],"limitations":["Very high amounts can feel sticky, especially in humid weather"],"adverseEffects":["Irritation is rare"],"precautions":[],"compatibility":["Compatible with almost all ingredients"],"applications":{"skin":"Moisturisers, cleansers, serums.","oral":"Humectant in toothpaste.","body":"Lotions, soaps."},"misconceptions":[{"myth":"Pure glycerin is the best moisturiser.","fact":"Undiluted glycerin is very sticky and can draw water from skin in dry air; it works best within a formulated product."}]}'::jsonb, '{"what":{"summary":"A humectant that attracts water; plant- or synthetically derived."},"why":{"summary":"To hydrate and soften skin and support the barrier.","points":["Evidence: established"]},"when":{"summary":"Daily, as part of a moisturiser or cleanser."},"who":{"summary":"Almost everyone, including sensitive and dry skin."},"where":{"summary":"Face, body, hands, lips; also oral-care products."},"how":{"summary":"Use a formulated product rather than pure glycerin."}}'::jsonb, '{"skinTypes":["oily","dry","combination","normal","sensitive"],"skinConcerns":["dryness","irritation"]}'::jsonb, 'published', '2026-10-10');
