insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('ceramides', 'Ceramides', 'Ceramide NP / AP / EOP / NS', 'Barrier lipid', 'full', 'Lipids naturally found in the outer layer of the skin. Added to moisturisers to help support a damaged or dry skin barrier, often with cholesterol and fatty acids.', array['Barrier repair', 'Skin conditioning', 'Emollient']::text[], array['Moisturisers', 'Barrier creams', 'Cleansers']::text[], 'moderate', 'Barrier creams containing ceramides help dry skin and are used in eczema care. Benefit depends on the whole formula; the specific ceramide amount is rarely disclosed.', null, null, '{}'::text[], '{"benefits":["Supports barrier repair in dry or irritated skin","Can reduce dryness and tightness","Useful alongside drying acne treatments"],"limitations":["Products rarely disclose ceramide amount; a ceramide listed near the end may be present in small quantity","Not clearly better than other well-formulated moisturisers for everyone"],"adverseEffects":["Rare; reactions usually relate to other ingredients"],"precautions":[],"compatibility":["Pairs well with retinoids and acne treatments to reduce dryness"],"applications":{"skin":"Moisturisers and barrier creams.","body":"Body lotions for dry skin."},"forms":[{"name":"Ceramide NP, AP, EOP, NS","note":"Different ceramide types; labels list them by these INCI names."},{"name":"Pseudo-ceramides","note":"Synthetic ceramide-like lipids; may act similarly."}]}'::jsonb, '{"what":{"summary":"Skin-identical lipids that form part of the barrier between skin cells."},"why":{"summary":"To help restore a dry, tight or irritated barrier."},"when":{"summary":"Daily; especially in winter, in air-conditioning, or while using drying actives."},"who":{"summary":"Dry, sensitive or irritated skin; anyone using retinoids or acne treatments."},"where":{"summary":"Face and body."},"how":{"summary":"Apply moisturiser to clean, slightly damp skin once or twice daily."}}'::jsonb, '{"skinTypes":["dry","sensitive","normal","combination"],"skinConcerns":["dryness","irritation"],"climates":["hot_dry","cold"]}'::jsonb, 'published', '2026-10-11');
