insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('retinoids', 'Retinoids (Retinol & related)', 'Retinol / Retinal / Retinyl Palmitate', 'Vitamin A derivative / active', 'full', 'A family of vitamin A derivatives. Prescription retinoids (e.g. tretinoin, adapalene) have strong evidence for acne and sun-related ageing; cosmetic retinol and esters are weaker and work more slowly.', array['Cell turnover', 'Acne treatment (prescription forms)', 'Photo-ageing treatment']::text[], array['Serums', 'Night creams', 'Prescription gels']::text[], 'established', 'Strong evidence for prescription retinoids (tretinoin, adapalene) in acne and photo-ageing. Evidence for over-the-counter retinol is moderate; for retinyl esters, weaker.', 'Prescription strengths are set by the prescriber. Cosmetic retinol percentages vary widely and are not standardised across brands.', null, array['potential_irritant', 'photosensitising', 'pregnancy_caution']::text[], '{"benefits":["Prescription forms treat acne and improve sun-related skin changes","Cosmetic retinol may improve texture and fine lines over months"],"limitations":["Irritation (\"retinisation\") is common in the first weeks","Results take months","Cosmetic retinol is not equivalent to prescription retinoids"],"adverseEffects":["Dryness, peeling, redness, stinging","Increased sun sensitivity"],"precautions":["Avoid during pregnancy or when planning pregnancy unless a doctor advises otherwise","Use sunscreen daily","Do not use on broken, sunburnt or eczematous skin","Prescription retinoids should be used under medical guidance"],"compatibility":["Introduce separately from acids and benzoyl peroxide; some combinations are prescribed together by doctors","Pair with a simple moisturiser"],"applications":{"skin":"Night serums and creams; prescription acne gels."},"forms":[{"name":"Retinyl esters (palmitate, acetate)","note":"Mildest, least evidence."},{"name":"Retinol","note":"Common cosmetic form; converted in the skin, moderate evidence."},{"name":"Retinaldehyde (retinal)","note":"One step closer to the active form; cosmetic."},{"name":"Adapalene, tretinoin","note":"Prescription-only in India; strongest evidence for acne."}],"misconceptions":[{"myth":"Peeling means it is working.","fact":"Some peeling is common at first, but heavy irritation means you should reduce frequency."},{"myth":"Retinol thins the skin.","fact":"Retinoids thin the outermost dead layer temporarily but are associated with thicker underlying skin over time; irritation is the main practical issue."}]}'::jsonb, '{"what":{"summary":"Vitamin A derivatives ranging from mild cosmetic esters to prescription drugs."},"why":{"summary":"To treat acne or improve sun-related texture and fine lines.","points":["Not necessary for everyone","Prescription forms have the strongest evidence"]},"when":{"summary":"At night, starting 2–3 times a week and increasing as tolerated.","points":["Avoid during pregnancy","Pause on sunburnt or irritated skin"]},"who":{"summary":"Adults with acne or sun-related ageing concerns.","points":["Caution: sensitive skin, rosacea, eczema","Not for pregnancy unless advised by a doctor"]},"where":{"summary":"Face (avoid the eye corners, nostrils and lips), sometimes neck and chest."},"how":{"summary":"A pea-sized amount for the whole face on dry skin, then moisturiser. Sunscreen every morning.","points":["Common mistake: starting nightly with a strong product","Common mistake: skipping sunscreen"]}}'::jsonb, '{"skinTypes":["oily","combination","normal"],"skinConcerns":["acne","texture","uneven_tone"],"cautionFor":["pregnancy","sensitive_skin","sun_exposure"]}'::jsonb, 'published', '2026-10-09');
