insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('vitamin-c', 'Vitamin C', 'Ascorbic Acid and derivatives', 'Antioxidant / active', 'full', 'An antioxidant used to help with dullness and uneven tone and to add protection alongside sunscreen. Pure L-ascorbic acid is the most studied form but is unstable; derivatives are more stable but less studied.', array['Antioxidant', 'Tone evening', 'Supports sunscreen protection (not a replacement)']::text[], array['Serums', 'Moisturisers']::text[], 'moderate', 'Several studies of L-ascorbic acid (often around 10–20%, low pH) show modest benefits. Evidence for most derivatives is limited and form-specific.', 'Studies of L-ascorbic acid commonly used about 10–20%. Derivative strengths are not directly comparable to L-ascorbic acid.', null, array['potential_irritant']::text[], '{"benefits":["May improve uneven tone and dullness","Antioxidant support alongside sunscreen"],"limitations":["L-ascorbic acid oxidises (turns yellow/brown) with air, light and heat","Does not replace sunscreen","Derivative claims often rely on lab data"],"adverseEffects":["Stinging or tingling with low-pH L-ascorbic acid","Temporary yellowish staining from oxidised serums"],"precautions":["Store away from heat and sunlight — relevant in Indian summers","Discard serums that have turned dark brown"],"compatibility":["Can be used with sunscreen in the morning","If combined with acids or retinoids causes stinging, separate them"],"applications":{"skin":"Morning serums for dullness and uneven tone."},"forms":[{"name":"L-ascorbic acid","note":"Most evidence; least stable; needs low pH."},{"name":"Sodium / magnesium ascorbyl phosphate","note":"More stable, gentler; less evidence."},{"name":"Ascorbyl glucoside, ethyl ascorbic acid","note":"Stable derivatives; evidence mostly from manufacturer or lab studies."}]}'::jsonb, '{"what":{"summary":"An antioxidant vitamin available as pure L-ascorbic acid or more stable derivatives."},"why":{"summary":"For dullness and uneven tone, and as antioxidant support under sunscreen."},"when":{"summary":"Usually in the morning, before sunscreen.","points":["Stop if persistent stinging"]},"who":{"summary":"Most skin types; those with sensitive skin may prefer gentler derivatives."},"where":{"summary":"Face and neck."},"how":{"summary":"A few drops on clean skin, then moisturiser and sunscreen.","points":["Keep the bottle closed, cool and dark","Common mistake: using an oxidised serum"]}}'::jsonb, '{"skinTypes":["oily","combination","normal","dry"],"skinConcerns":["uneven_tone","sun_protection"]}'::jsonb, 'published', '2026-10-08');
