insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('benzoyl-peroxide', 'Benzoyl Peroxide', 'Benzoyl Peroxide', 'Acne active (antibacterial)', 'full', 'An antibacterial acne treatment that reduces C. acnes bacteria and helps inflamed pimples. Often prescribed alongside other acne treatments.', array['Reduces acne-causing bacteria', 'Mild comedolytic']::text[], array['Gels', 'Washes', 'Spot treatments']::text[], 'established', 'Long-standing, well-established acne treatment recognised in acne guidelines and the US FDA acne monograph (2.5–10%).', 'US FDA OTC acne monograph: 2.5–10%. Lower strengths (around 2.5%) are often better tolerated.', null, array['potential_irritant', 'drying']::text[], '{"benefits":["Effective for inflamed acne","Bacteria do not become resistant to it the way they can to antibiotics"],"limitations":["Dryness and irritation are common","Bleaches fabrics, towels and hair"],"adverseEffects":["Dryness, peeling, redness","Rarely, allergic contact dermatitis"],"precautions":["Start with a low strength and short contact time","Use white pillowcases/towels or expect bleaching","Use sunscreen and a moisturiser","In India, many strengths are dispensed as medicines — follow the label or prescriber"],"compatibility":["Avoid layering with other strong actives at the same time unless prescribed","Some retinoid–BPO combinations are prescribed together"],"applications":{"skin":"Leave-on gels and wash-off cleansers for acne on face, chest and back."}}'::jsonb, '{"what":{"summary":"An antibacterial, oxidising acne treatment."},"why":{"summary":"To reduce inflamed pimples by lowering acne bacteria.","points":["Evidence: established"]},"when":{"summary":"Once daily to start, often in the evening.","points":["Stop and seek advice for swelling, blistering or severe burning"]},"who":{"summary":"People with inflamed acne.","points":["Caution: very dry or sensitive skin"]},"where":{"summary":"Acne-prone areas: face, chest, back.","points":["Avoid eyes, lips, mouth and broken skin"]},"how":{"summary":"Thin layer on affected areas, or use as a short-contact wash and rinse.","points":["Common mistake: dabbing high strength on single spots many times a day"]}}'::jsonb, '{"skinTypes":["oily","combination"],"skinConcerns":["acne"],"cautionFor":["sensitive_skin"]}'::jsonb, 'published', '2026-10-08');
