insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('zinc-oxide', 'Zinc Oxide', 'Zinc Oxide', 'Mineral UV filter', 'full', 'A mineral sunscreen filter that protects across UVB and UVA. Also used as a soothing skin protectant.', array['UV filter (UVB and UVA)', 'Skin protectant']::text[], array['Mineral sunscreens', 'Nappy creams', 'Calamine-type lotions']::text[], 'established', 'Recognised sunscreen active by regulators; US FDA lists it among filters generally recognised as safe and effective (up to 25%).', 'Up to 25% as a sunscreen active (US FDA).', null, '{}'::text[], '{"benefits":["Broad UV protection, including long-wave UVA","Generally well tolerated by sensitive skin","Photostable"],"limitations":["Can leave a white cast, more visible on deeper skin tones","Can feel heavy; protection depends on applying enough"],"adverseEffects":["Rarely irritating; may feel occlusive on acne-prone skin depending on the formula"],"precautions":["Avoid inhaling powder or spray forms"],"compatibility":["Often combined with other filters for better texture"],"applications":{"skin":"Mineral and hybrid sunscreens; protectant creams."},"forms":[{"name":"Non-nano zinc oxide","note":"Larger particles; more white cast."},{"name":"Nano / micronised zinc oxide","note":"Less white cast; evaluated as safe on intact skin by EU SCCS in specified conditions (not for sprays)."}]}'::jsonb, '{"what":{"summary":"A mineral UV filter covering UVB and UVA."},"why":{"summary":"Sun protection, especially for sensitive skin."},"when":{"summary":"Every day when outdoors or near windows; reapply after 2 hours in the sun, sweating or swimming."},"who":{"summary":"Everyone; often preferred for sensitive skin and children."},"where":{"summary":"All exposed skin, including ears and neck.","points":["Avoid inhaling sprays/powders"]},"how":{"summary":"Apply generously; for the face and neck, about two finger-lengths is a commonly cited guide.","points":["Common mistake: applying too little to avoid white cast"]}}'::jsonb, '{"skinTypes":["oily","dry","combination","normal","sensitive"],"skinConcerns":["sun_protection","irritation"]}'::jsonb, 'published', '2026-10-07');
