insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('titanium-dioxide', 'Titanium Dioxide', 'Titanium Dioxide', 'Mineral UV filter / pigment', 'full', 'A mineral UV filter that mainly protects against UVB and shorter UVA, often combined with zinc oxide or other filters. Also used as a white pigment.', array['UV filter (mainly UVB and short UVA)', 'White pigment / opacifier']::text[], array['Sunscreens', 'Makeup', 'Toothpastes (as colourant)']::text[], 'established', 'Recognised sunscreen active (US FDA, up to 25%). Weaker against long-wave UVA than zinc oxide.', 'Up to 25% as a sunscreen active (US FDA).', null, '{}'::text[], '{"benefits":["Photostable UV protection","Generally well tolerated"],"limitations":["Less long-UVA protection than zinc oxide","White cast"],"adverseEffects":["Rarely irritating"],"precautions":["Avoid inhaling powders and sprays — inhalation is the main safety concern, not use on skin"],"applications":{"skin":"Sunscreens and makeup.","oral":"Whitening pigment in some toothpastes."}}'::jsonb, '{"what":{"summary":"A mineral UV filter and white pigment."},"why":{"summary":"UV protection in sunscreens; colour in cosmetics."},"when":{"summary":"Daily as part of sunscreen; reapply when outdoors."},"who":{"summary":"Everyone; often used in products for sensitive skin."},"where":{"summary":"Exposed skin.","points":["Avoid inhaling powders/sprays"]},"how":{"summary":"Apply sunscreen generously and evenly."}}'::jsonb, '{"skinConcerns":["sun_protection"],"skinTypes":["sensitive","normal","dry","oily","combination"]}'::jsonb, 'published', '2026-10-07');
