insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('fluoride', 'Fluoride', 'Sodium Fluoride / Sodium Monofluorophosphate / Stannous Fluoride', 'Anti-cavity active', 'full', 'The best-established ingredient for preventing tooth decay. It helps enamel resist acid and repairs early damage.', array['Prevents tooth decay', 'Strengthens enamel', 'Stannous form: reduces sensitivity and gingivitis']::text[], array['Toothpastes', 'Mouth rinses', 'Professional varnishes']::text[], 'established', 'Fluoride toothpaste is recommended by WHO and dental associations as a core measure for preventing tooth decay.', 'Many international guidelines refer to about 1000–1500 ppm fluoride in adult toothpaste. Indian packs declare fluoride content in ppm; check the label.', null, '{}'::text[], '{"benefits":["Reduces cavities (strong evidence)","Helps remineralise early enamel lesions","Stannous fluoride also helps with gum inflammation and sensitivity"],"limitations":["Works best with twice-daily brushing and less frequent sugar intake","Does not replace dental check-ups"],"adverseEffects":["Swallowing too much toothpaste in early childhood can cause dental fluorosis (white marks on teeth)","Stannous fluoride may cause surface staining in some people"],"precautions":["Children under 3: a smear (rice-grain size); 3–6 years: a pea-sized amount, with supervision","Some regions of India have naturally high fluoride in groundwater; ask a dentist about children''s total exposure","Spit, do not swallow"],"compatibility":["Avoid rinsing with lots of water immediately after brushing to keep fluoride on teeth"],"applications":{"oral":"Toothpastes, mouth rinses, professional varnish."},"forms":[{"name":"Sodium fluoride (NaF)","note":"Common in toothpastes."},{"name":"Sodium monofluorophosphate (SMFP)","note":"Common in many Indian toothpastes; compatible with calcium-based abrasives."},{"name":"Stannous fluoride (SnF2)","note":"Also anti-gingivitis and anti-sensitivity; may stain."}],"misconceptions":[{"myth":"Herbal toothpastes protect teeth just as well without fluoride.","fact":"For cavity prevention, fluoride has the strongest evidence. Many herbal toothpastes also contain fluoride — check the label."}],"faqs":[{"q":"Should I rinse after brushing?","a":"Spitting out excess paste without a heavy water rinse helps fluoride stay on the teeth longer."}]}'::jsonb, '{"what":{"summary":"A mineral ingredient in toothpastes that helps prevent cavities."},"why":{"summary":"To prevent tooth decay and strengthen enamel.","points":["Evidence: established (WHO, dental associations)"]},"when":{"summary":"Brush twice daily, including before bed."},"who":{"summary":"Almost everyone with teeth, including children in age-appropriate amounts.","points":["Children: supervise and use small amounts"]},"where":{"summary":"Teeth and gum line. Not to be swallowed."},"how":{"summary":"Brush for about two minutes, spit out, avoid heavy rinsing.","points":["Common mistake: using a large amount on a child''s brush"]}}'::jsonb, '{"oralConcerns":["cavities","sensitive_teeth","gum_care"],"cautionFor":["children"]}'::jsonb, 'published', '2026-10-05');
