insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('potassium-nitrate', 'Potassium Nitrate', 'Potassium Nitrate', 'Desensitising agent (oral care)', 'full', 'A common active in toothpastes for sensitive teeth. It calms the nerve response over several weeks of regular use.', array['Reduces tooth sensitivity (nerve desensitising)']::text[], array['Sensitive toothpastes']::text[], 'moderate', 'Systematic reviews generally find a benefit for dentine hypersensitivity, although study quality varies.', 'Commonly 5% in sensitivity toothpastes; check the label.', null, '{}'::text[], '{"benefits":["Can reduce sensitivity to cold, hot or sweet with regular use"],"limitations":["Takes about 2–4 weeks of twice-daily use","Does not treat the cause (gum recession, enamel wear, cavities)"],"adverseEffects":["Generally well tolerated"],"precautions":["Sudden or one-sided sensitivity, or pain that lingers, should be checked by a dentist"],"applications":{"oral":"Sensitive-teeth toothpastes."}}'::jsonb, '{"what":{"summary":"A desensitising salt in sensitive-teeth toothpastes."},"why":{"summary":"To reduce short, sharp sensitivity to cold, heat or sweets."},"when":{"summary":"Twice daily; benefit builds over weeks."},"who":{"summary":"People with dentine sensitivity.","points":["See a dentist if pain persists, wakes you up, or is in one tooth"]},"where":{"summary":"Teeth; some people also dab paste on sensitive spots."},"how":{"summary":"Brush gently with a soft brush; spit, do not rinse heavily."}}'::jsonb, '{"oralConcerns":["sensitive_teeth"]}'::jsonb, 'published', '2026-10-05');
