insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('coconut-oil', 'Coconut Oil', 'Cocos Nucifera (Coconut) Oil', 'Plant oil / emollient', 'full', 'A widely used traditional hair and body oil in India. As a pre-wash hair treatment it may reduce protein loss and breakage; on the body it is an effective emollient.', array['Emollient', 'Hair conditioning', 'Pre-wash hair treatment']::text[], array['Hair oils', 'Body moisturisers', 'Soaps (saponified)']::text[], 'moderate', 'Laboratory studies suggest coconut oil penetrates the hair shaft and reduces protein loss. Small clinical trials support it as a body moisturiser for dry skin. There is no good evidence it grows hair or stops hair fall.', null, 'Long-standing use for hair oiling and massage (abhyanga) across India, especially in the south and coastal regions.', array['comedogenic_possible']::text[], '{"benefits":["May reduce protein loss and damage from washing when used before shampoo","Effective emollient for dry body skin","Affordable and widely available"],"limitations":["No reliable evidence for hair growth or reversing hair fall","Can feel heavy on fine or oily hair","Can block pores on acne-prone facial skin for some people"],"adverseEffects":["May worsen acne on the face or forehead in some people","Leaving oil on the scalp for long periods may aggravate dandruff in some people"],"precautions":["If you have dandruff or seborrhoeic dermatitis, see whether heavy oiling worsens it","Wash off thoroughly; avoid oil near the hairline if you get forehead acne"],"compatibility":["Use as a pre-wash treatment followed by shampoo"],"applications":{"hair":"Pre-wash oiling and leave-in on ends.","body":"Moisturising dry skin.","oral":"Used in oil pulling (limited evidence; see topic)."},"misconceptions":[{"myth":"Coconut oil stops hair fall.","fact":"It can reduce breakage, which may look like less hair fall, but it does not treat genetic or medical hair loss."}],"faqs":[{"q":"Is coconut oil good for hair?","a":"As a pre-wash treatment it may reduce protein loss and breakage. It is not proven to grow hair or stop hair loss."}]}'::jsonb, '{"what":{"summary":"An oil pressed from coconut kernel, rich in lauric acid."},"why":{"summary":"To condition hair and reduce breakage; to moisturise dry body skin.","points":["Evidence: moderate for hair protein loss and dry skin; none for hair growth"]},"when":{"summary":"30 minutes to a few hours before washing, or overnight if your scalp tolerates it."},"who":{"summary":"Dry, curly, coily or damaged hair; dry body skin.","points":["Caution: acne-prone facial skin, dandruff-prone scalp","Avoid if allergic to coconut"]},"where":{"summary":"Hair lengths and ends; scalp if tolerated; body skin."},"how":{"summary":"Warm slightly (not hot), apply a small amount to lengths, then shampoo off.","points":["Common mistake: using very hot oil","Common mistake: leaving heavy oil on an itchy, flaky scalp for days"]}}'::jsonb, '{"hairConcerns":["breakage","frizz"],"scalp":["dry_scalp"],"skinTypes":["dry"],"skinConcerns":["dryness"]}'::jsonb, 'published', '2026-10-03');
