insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('aloe-vera', 'Aloe Vera', 'Aloe Barbadensis Leaf Juice / Extract', 'Botanical / humectant', 'full', 'A plant gel used for soothing and light hydration. Popular in India for sunburn and as a light moisturiser; scientific evidence is mixed.', array['Soothing', 'Humectant', 'Skin conditioning']::text[], array['Gels', 'Moisturisers', 'After-sun products', 'Shampoos']::text[], 'preliminary', 'Some small studies suggest benefits for minor burns and skin hydration; overall evidence is mixed and of limited quality (NCCIH).', null, 'Used in Ayurveda (Ghritkumari) and home care for skin soothing and minor burns.', '{}'::text[], '{"benefits":["Light, non-greasy hydration","Often feels soothing on mild sunburn"],"limitations":["Product \"aloe\" content varies widely and is rarely disclosed","Not a treatment for serious burns or infected wounds"],"adverseEffects":["Allergic contact dermatitis in some people","Fresh leaf latex (yellow sap) can irritate skin"],"precautions":["Patch test fresh gel","If using fresh leaf, drain the yellow latex and use clean tools","Do not take aloe latex orally — it is a strong laxative with safety concerns"],"compatibility":["Compatible with most routines"],"applications":{"skin":"Gels and after-sun products.","hair":"Some scalp and hair products."}}'::jsonb, '{"what":{"summary":"Gel from the inner leaf of the aloe plant."},"why":{"summary":"For light hydration and a soothing feel.","points":["Evidence: preliminary / mixed"]},"when":{"summary":"As needed; after sun exposure for mild redness.","points":["Seek care for blistering, large or severe burns"]},"who":{"summary":"Most people; oily skin may like the light texture.","points":["Caution: known plant allergies"]},"where":{"summary":"Face and body skin.","points":["Not on open or infected wounds"]},"how":{"summary":"Apply a thin layer of a stored, preserved gel or clean fresh gel.","points":["Common mistake: using fresh gel kept for days without refrigeration"]}}'::jsonb, '{"skinTypes":["oily","combination","normal"],"skinConcerns":["irritation","dryness"],"climates":["hot_humid","hot_dry"]}'::jsonb, 'published', '2026-10-02');
