insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('neem', 'Neem', 'Azadirachta Indica Leaf Extract / Seed Oil', 'Botanical (traditional)', 'full', 'A tree used extensively in Indian traditional care. Neem extracts show antimicrobial activity in laboratory studies, but good-quality clinical evidence for skin, hair or oral benefits is limited.', array['Traditional antimicrobial', 'Skin conditioning']::text[], array['Face washes', 'Soaps', 'Toothpastes', 'Hair oils', 'Shampoos']::text[], 'preliminary', 'Mostly laboratory and small clinical studies. Not established as equivalent to proven acne, dandruff or anti-cavity actives.', null, 'Used in Ayurveda (Nimba) for skin conditions and oral hygiene; neem twigs are traditionally chewed as toothbrushes.', array['potential_irritant']::text[], '{"benefits":["Antimicrobial activity in laboratory studies","Long tradition of use in oral hygiene (neem twig, \"datun\") and skin care"],"limitations":["Extract strength and quality vary widely","Not a substitute for fluoride for cavity prevention"],"adverseEffects":["Allergic contact dermatitis","Neem oil is toxic if swallowed, especially for infants and young children"],"precautions":["Never give neem oil orally to children","Patch test leaf pastes and oils","Keep neem oil out of reach of children"],"applications":{"skin":"Face washes and soaps.","hair":"Hair oils and anti-dandruff positioning.","oral":"Toothpastes and traditional chewing sticks."},"misconceptions":[{"myth":"Neem is natural, so it is completely safe.","fact":"Neem can cause allergies, and neem oil is poisonous if swallowed by children."}]}'::jsonb, '{"what":{"summary":"Leaves, oil and extracts of the neem tree (Azadirachta indica)."},"why":{"summary":"Used traditionally for its antimicrobial reputation in skin, scalp and oral care.","points":["Evidence: preliminary — mostly lab studies"]},"when":{"summary":"As part of a formulated product as directed."},"who":{"summary":"Adults who prefer botanical products and tolerate them.","points":["Caution: allergies; keep neem oil away from children"]},"where":{"summary":"Skin, scalp, mouth (in formulated products).","points":["Do not swallow neem oil"]},"how":{"summary":"Prefer formulated products over home-made oils; patch test first."}}'::jsonb, '{"skinConcerns":["acne"],"hairConcerns":["dandruff"],"oralConcerns":["gum_care"],"cautionFor":["children"]}'::jsonb, 'published', '2026-10-02');
