insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('amla', 'Amla (Indian Gooseberry)', 'Phyllanthus Emblica Fruit Extract', 'Botanical (traditional)', 'full', 'A fruit used in Ayurveda (Amalaki) and widely in Indian hair oils. Rich in antioxidants in laboratory analysis; claims for hair growth or preventing greying are not established.', array['Antioxidant (lab)', 'Traditional hair tonic']::text[], array['Hair oils', 'Shampoos', 'Hair dyes (with henna)']::text[], 'traditional', 'Long traditional use. Evidence for hair growth or greying is limited to preliminary and laboratory studies.', null, 'Amalaki is used in Ayurveda and in hair care traditions such as amla–shikakai–reetha mixtures.', '{}'::text[], '{"benefits":["Antioxidant activity in laboratory studies","Commonly used as a hair oil base or conditioner"],"limitations":["\"Amla hair oil\" products are often mostly mineral or vegetable oil with a small amount of amla extract","Not proven to prevent greying or hair loss"],"adverseEffects":["Allergic reactions are possible","Some amla hair oils contain added fragrance or mineral oil"],"precautions":["Patch test before scalp use","Hair-fall that is sudden or patchy should be assessed by a doctor"],"applications":{"hair":"Hair oils, shampoos and henna mixes."}}'::jsonb, '{"what":{"summary":"The Indian gooseberry fruit, used as extract, powder or infused oil."},"why":{"summary":"Traditionally used as a hair tonic.","points":["Evidence: traditional / preliminary"]},"when":{"summary":"As a pre-wash hair oil or in shampoos."},"who":{"summary":"Those who prefer traditional hair care.","points":["Not a treatment for medical hair loss"]},"where":{"summary":"Scalp and hair."},"how":{"summary":"Use a formulated oil and wash off; read the full ingredient list to see what the base oil is."}}'::jsonb, '{"hairConcerns":["hair_fall","breakage"]}'::jsonb, 'needs_verification', '2026-09-28');
