insert into ingredients (id, name, inci, kind, tier, summary, functions, product_types, evidence_level, evidence_summary, concentrations, traditional_use, flags, details, five_w, suitability, status, last_reviewed) values ('turmeric', 'Turmeric', 'Curcuma Longa (Turmeric) Root Extract', 'Botanical (traditional)', 'full', 'A spice with a long tradition in Indian skin care (haldi, ubtan). Curcumin shows anti-inflammatory and antioxidant effects in lab studies, but topical clinical evidence is limited.', array['Antioxidant (lab)', 'Traditional anti-inflammatory', 'Colourant']::text[], array['Face packs (ubtan)', 'Creams', 'Soaps']::text[], 'preliminary', 'NCCIH notes limited evidence for most uses. Small studies of topical curcumin exist, but the evidence is not strong enough to rely on for acne or pigmentation.', null, 'Haridra in Ayurveda; used in ubtan and haldi ceremonies.', array['potential_irritant']::text[], '{"benefits":["Traditional part of ubtan and wedding rituals","Antioxidant and anti-inflammatory activity in laboratory research"],"limitations":["Stains skin, nails, clothing yellow","Kitchen turmeric quality varies; adulteration has been reported in some markets"],"adverseEffects":["Allergic contact dermatitis reported","Irritation when mixed with lemon or other acids"],"precautions":["Patch test home-made packs","Do not apply to open wounds","Use clean, good-quality turmeric"],"applications":{"skin":"Traditional face packs and some creams."}}'::jsonb, '{"what":{"summary":"Turmeric root powder or extract, containing curcuminoids."},"why":{"summary":"Traditionally used for skin glow and blemishes.","points":["Evidence: preliminary"]},"when":{"summary":"Occasionally, as a wash-off pack."},"who":{"summary":"People without turmeric allergy who want a traditional pack.","points":["Caution: sensitive skin"]},"where":{"summary":"Face and body skin (intact skin only)."},"how":{"summary":"Mix a small amount with plain yoghurt, besan or water; leave briefly, rinse.","points":["Common mistake: adding lemon juice"]}}'::jsonb, '{"skinConcerns":["uneven_tone"],"cautionFor":["sensitive_skin"]}'::jsonb, 'published', '2026-09-28');
