insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('acne', 'Acne (pimples)', 'concern', null, 'Blocked pores and inflammation causing blackheads, whiteheads and red or painful bumps. Very common in teenagers and adults; humid weather and sweat can aggravate it for some people.', array['pimples', 'pimple', 'breakouts', 'zits', 'acne vulgaris', 'blackheads', 'whiteheads', 'muhase', 'kil']::text[], null, null, '[{"claim":"Benzoyl peroxide, salicylic acid and retinoids help acne","level":"established"},{"claim":"Niacinamide may help mild acne","level":"moderate"},{"claim":"Toothpaste dries out pimples","level":"unsupported","note":"Can irritate and burn the skin."}]'::jsonb, '{"seeProfessional":["Painful nodules or cysts","Acne leaving scars or dark marks","No improvement after 8–12 weeks of OTC care","Sudden adult acne with irregular periods or excess hair growth"]}'::jsonb, '{"what":{"summary":"A condition of the hair follicles and oil glands with clogged pores, bacteria and inflammation."},"why":{"summary":"Treating early can reduce scarring and post-acne marks, which are often more noticeable on brown skin."},"when":{"summary":"OTC treatments are reasonable for mild acne; give each change 8–12 weeks.","points":["See a dermatologist earlier for painful or scarring acne"]},"who":{"summary":"Teenagers and adults of all skin types."},"where":{"summary":"Face, chest, shoulders and back."},"how":{"summary":"Gentle cleanser, one proven active at a time, non-comedogenic moisturiser, daily sunscreen.","points":["Avoid picking or squeezing","Common mistake: using many actives at once"]}}'::jsonb, '{"skinConcerns":["acne"],"skinTypes":["oily","combination"]}'::jsonb, 'published', '2026-10-10');
