insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('dandruff', 'Dandruff', 'concern', null, 'Flaking and itching of the scalp, linked to Malassezia yeast and individual sensitivity. Usually manageable with anti-dandruff shampoos.', array['flakes', 'flaky scalp', 'itchy scalp', 'seborrheic dermatitis', 'seborrhoeic dermatitis', 'rusi']::text[], null, null, '[{"claim":"Antifungal shampoos (ketoconazole, zinc pyrithione, selenium sulfide) reduce dandruff","level":"established"},{"claim":"Heavy oiling cures dandruff","level":"unsupported","note":"Oil can feed Malassezia; it may worsen flaking for some."},{"claim":"Neem helps dandruff","level":"preliminary"}]'::jsonb, '{"seeProfessional":["Thick, yellow crusts or bleeding","Red patches spreading beyond the scalp","No improvement after 4 weeks of anti-dandruff shampoo"]}'::jsonb, '{"what":{"summary":"Visible white or yellow flakes with itching, from an inflammatory reaction on the scalp."},"why":{"summary":"Treating reduces itching and visible flakes; it tends to recur, so ongoing control is normal."},"when":{"summary":"Use an anti-dandruff shampoo 2–3 times a week until controlled, then weekly."},"who":{"summary":"Adults and teenagers; more common with oily scalp."},"where":{"summary":"Scalp; sometimes eyebrows and sides of the nose."},"how":{"summary":"Massage shampoo into the scalp and leave on for 3–5 minutes before rinsing.","points":["Common mistake: rinsing immediately","Common mistake: heavy oil left overnight on a flaky scalp"]}}'::jsonb, '{"hairConcerns":["dandruff"],"scalp":["oily_scalp"]}'::jsonb, 'published', '2026-10-09');
