insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('sensitive-teeth', 'Sensitive teeth', 'concern', null, 'Short, sharp pain with cold, hot, sweet or acidic foods, usually from exposed dentine due to gum recession or enamel wear.', array['tooth sensitivity', 'dentine hypersensitivity', 'dentin hypersensitivity', 'teeth sensitivity', 'sensitive tooth', 'cold sensitivity']::text[], null, null, '[{"claim":"Potassium nitrate and stannous fluoride toothpastes reduce sensitivity","level":"moderate"},{"claim":"Brushing harder cleans better","level":"unsupported","note":"Hard brushing can worsen gum recession and sensitivity."}]'::jsonb, '{"seeProfessional":["Pain lasting more than a few seconds","Pain in one tooth or when biting","Swelling or pain that wakes you up"]}'::jsonb, '{"what":{"summary":"Brief sharp pain from exposed dentine reacting to temperature or sweetness."},"why":{"summary":"Desensitising toothpastes can reduce discomfort; the cause still needs attention."},"when":{"summary":"Use a sensitivity toothpaste twice daily for at least 2–4 weeks."},"who":{"summary":"Adults with gum recession, enamel wear, or after whitening."},"where":{"summary":"Usually near the gum line."},"how":{"summary":"Soft brush, gentle technique, spit don''t rinse; limit acidic drinks.","points":["Common mistake: using a hard brush with heavy pressure"]}}'::jsonb, '{"oralConcerns":["sensitive_teeth"]}'::jsonb, 'published', '2026-10-05');
