insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('hair-fall', 'Hair fall', 'concern', null, 'Losing some hair daily is normal. Increased shedding can follow illness, stress, childbirth, crash dieting or deficiencies; gradual thinning is often genetic. Breakage is different from hair falling from the root.', array['hair loss', 'hairfall', 'hair falling', 'thinning hair', 'baldness', 'balding', 'hair thinning', 'baal jhadna']::text[], null, null, '[{"claim":"Topical minoxidil helps pattern hair loss","level":"established","note":"A medicine; use on medical advice."},{"claim":"Hair oils stop hair fall","level":"unsupported","note":"Oils may reduce breakage but do not treat root shedding."},{"claim":"Onion juice regrows hair","level":"preliminary","note":"Very small studies; can irritate the scalp."}]'::jsonb, '{"seeProfessional":["Sudden or patchy hair loss","Hair loss with fatigue, weight change or irregular periods","Scalp redness, scaling or pain","Visible thinning that is progressing"]}'::jsonb, '{"what":{"summary":"Shedding from the root (hair fall) or snapping of the shaft (breakage)."},"why":{"summary":"Identifying the type matters: breakage responds to gentler care; shedding often needs medical evaluation."},"when":{"summary":"Seek a doctor for sudden, patchy or progressive loss."},"who":{"summary":"Anyone; patterns differ by sex, age and health."},"where":{"summary":"Scalp, hairline, crown or all over."},"how":{"summary":"Gentle handling, balanced diet, avoid tight hairstyles; get medical assessment rather than switching oils repeatedly."}}'::jsonb, '{"hairConcerns":["hair_fall","breakage"]}'::jsonb, 'published', '2026-10-04');
