insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('pigmentation', 'Uneven tone & pigmentation', 'concern', null, 'Dark marks after acne, sun spots and melasma. Common on Indian skin; sun protection is the foundation of any approach.', array['dark spots', 'pigmentation', 'hyperpigmentation', 'melasma', 'tan', 'tanning', 'uneven skin tone', 'dark marks', 'pih', 'post inflammatory hyperpigmentation', 'brightening']::text[], null, null, '[{"claim":"Daily sunscreen helps prevent darkening","level":"established"},{"claim":"Niacinamide, azelaic acid and vitamin C may help fade marks","level":"moderate"},{"claim":"Lemon juice lightens spots","level":"unsupported","note":"Can cause irritation and phytophotodermatitis."}]'::jsonb, '{"seeProfessional":["A spot that changes in size, shape or colour","Melasma not improving with sunscreen","Using unlabelled \"fairness\" creams (may contain steroids)"]}'::jsonb, '{"what":{"summary":"Areas of skin darker than the surrounding skin from extra melanin."},"why":{"summary":"Mainly cosmetic, but changing spots need medical evaluation."},"when":{"summary":"Sunscreen daily; actives over 8–12 weeks."},"who":{"summary":"All skin tones; brown skin is more prone to post-inflammatory marks."},"where":{"summary":"Face, neck, arms."},"how":{"summary":"Daily broad-spectrum sunscreen plus one tone-evening active.","points":["Avoid steroid-containing \"fairness\" creams"]}}'::jsonb, '{"skinConcerns":["uneven_tone","sun_protection"]}'::jsonb, 'published', '2026-10-06');
