insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('sun-safety', 'Everyday sun protection', 'lifestyle', 'sun', 'UV exposure is high across much of India for most of the year. Sunscreen, shade and clothing together reduce tanning, sunburn and long-term damage.', array['sunscreen', 'spf', 'sun protection', 'uv protection', 'sunblock', 'pa rating', 'pa+++', 'tan prevention']::text[], null, null, '[{"claim":"Sunscreen reduces sunburn and UV damage","level":"established"},{"claim":"Dark skin does not need sunscreen","level":"unsupported","note":"Darker skin burns less but still tans, develops pigmentation and UV damage."}]'::jsonb, '{}'::jsonb, '{"what":{"summary":"Using sunscreen, shade, hats and clothing to limit UV exposure."},"why":{"summary":"To reduce sunburn, tanning, pigmentation and long-term skin damage."},"when":{"summary":"Daily when outdoors or near windows; reapply every 2 hours in the sun and after sweating.","points":["Midday sun (roughly 10 am–4 pm) is strongest"]},"who":{"summary":"Everyone, including darker skin tones.","points":["Babies under 6 months: shade and clothing first; ask a doctor"]},"where":{"summary":"Face, ears, neck, hands, arms and other exposed areas."},"how":{"summary":"Use enough: about two finger-lengths for face and neck. Choose broad-spectrum (UVA + UVB); PA+++ or higher indicates stronger UVA protection.","points":["Common mistake: applying too little","Common mistake: relying on makeup SPF alone"]}}'::jsonb, '{"skinConcerns":["sun_protection","uneven_tone"]}'::jsonb, 'published', '2026-10-11');
