insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('patch-testing', 'Patch testing a new product', 'practice', 'habits', 'Trying a new product on a small area for a few days before regular use helps spot irritation or allergy early.', array['patch test', 'allergy test', 'skin test', 'test new product']::text[], null, null, '[{"claim":"A home patch test can identify obvious reactions","level":"moderate","note":"It cannot rule out every allergy, and is not a substitute for dermatologist patch testing."}]'::jsonb, '{}'::jsonb, '{"what":{"summary":"Applying a small amount of product to a test area and watching for a reaction."},"why":{"summary":"To avoid a reaction across the whole face."},"when":{"summary":"Before using any new leave-on product, especially actives, fragrances and home remedies."},"who":{"summary":"Everyone; especially sensitive or allergy-prone skin."},"where":{"summary":"Inner forearm or behind the ear; for face products, also a small patch near the jawline."},"how":{"summary":"Apply once or twice daily to the same spot for several days; stop if redness, itching or swelling appears.","points":["Delayed allergic reactions can take 48–72 hours"]}}'::jsonb, '{}'::jsonb, 'published', '2026-10-01');
