insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('flossing', 'Cleaning between teeth', 'practice', 'oral-tools', 'Brushing does not reach between teeth. Floss or interdental brushes help remove plaque there.', array['floss', 'flossing', 'interdental brush', 'interdental cleaning', 'dental floss']::text[], null, null, '[{"claim":"Interdental cleaning reduces gum inflammation","level":"moderate"}]'::jsonb, '{}'::jsonb, '{"what":{"summary":"Using floss, interdental brushes or water flossers between teeth."},"why":{"summary":"To reduce plaque and gum inflammation where the brush cannot reach."},"when":{"summary":"Once a day."},"who":{"summary":"Adults and older children; people with braces or gaps may prefer interdental brushes."},"where":{"summary":"Between every tooth and along the gum line."},"how":{"summary":"Gently curve the floss around each tooth; slight bleeding at first often settles in a week or two.","points":["Persistent bleeding: see a dentist"]}}'::jsonb, '{"oralConcerns":["gum_care","bad_breath"]}'::jsonb, 'published', '2026-09-30');
