insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('monsoon-skin-care', 'Monsoon skin & foot care', 'lifestyle', 'seasonal', 'Humidity and wet clothing during the monsoon raise the risk of fungal skin infections and itchy rashes, especially in skin folds and feet.', array['monsoon', 'rainy season', 'fungal infection', 'ringworm', 'athletes foot', 'humidity', 'barsaat']::text[], null, null, '[{"claim":"Keeping skin folds and feet dry reduces fungal infections","level":"established"},{"claim":"Over-the-counter steroid-antifungal combination creams are a good fix","level":"unsupported","note":"Such combinations are linked to persistent, hard-to-treat ringworm in India."}]'::jsonb, '{"seeProfessional":["Itchy ring-shaped rash that spreads","Rash not improving in 2 weeks","Diabetes with foot wounds"]}'::jsonb, '{"what":{"summary":"Habits to manage skin during the humid, wet season."},"why":{"summary":"Moisture and friction encourage fungal and bacterial infections."},"when":{"summary":"Roughly June–September for most regions (southwest monsoon); Oct–Dec in Tamil Nadu and nearby coasts."},"who":{"summary":"Everyone; especially people with diabetes, those who sweat heavily, and commuters in wet footwear."},"where":{"summary":"Feet, groin, underarms, under the breasts, waist."},"how":{"summary":"Dry skin folds after bathing, change out of damp clothes, wear breathable fabrics, keep footwear dry.","points":["Avoid unprescribed steroid creams on rashes"]}}'::jsonb, '{"climates":["monsoon","hot_humid"]}'::jsonb, 'published', '2026-10-02');
