insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('sweat-hygiene', 'Summer sweat & body odour', 'lifestyle', 'habits', 'Sweat itself is odourless; odour comes from bacteria breaking it down. Antiperspirants reduce sweat; deodorants mask or reduce odour.', array['body odour', 'body odor', 'sweating', 'sweat', 'deodorant', 'antiperspirant', 'bo', 'prickly heat', 'heat rash', 'ghamoriyan']::text[], null, null, '[{"claim":"Aluminium antiperspirants cause breast cancer","level":"unsupported","note":"Reviews have not established a link."}]'::jsonb, '{"seeProfessional":["Sudden change in body odour","Excessive sweating affecting daily life","Night sweats with weight loss"]}'::jsonb, '{"what":{"summary":"Managing sweat and odour in hot weather."},"why":{"summary":"Comfort, hygiene and preventing heat rash."},"when":{"summary":"Daily in summer; antiperspirants work best applied at night."},"who":{"summary":"Everyone; adolescents especially."},"where":{"summary":"Underarms, feet, skin folds."},"how":{"summary":"Bathe daily, dry thoroughly, choose breathable cotton, use antiperspirant if sweat is the issue."}}'::jsonb, '{"climates":["hot_humid","hot_dry"]}'::jsonb, 'published', '2026-10-01');
