insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('winter-dryness', 'Winter dryness', 'lifestyle', 'seasonal', 'Cold, dry air in north India and hill regions, plus hot baths, can leave skin dry, cracked and itchy.', array['dry skin winter', 'cracked heels', 'chapped lips', 'winter skin', 'xerosis', 'dry skin']::text[], null, null, '[{"claim":"Moisturising right after bathing reduces dryness","level":"established"}]'::jsonb, '{}'::jsonb, '{"what":{"summary":"Seasonal dryness from low humidity and cold."},"why":{"summary":"Dry skin can itch, crack and flare eczema."},"when":{"summary":"Roughly December–February in north and central India; longer in hill regions."},"who":{"summary":"Everyone in cold, dry regions; older adults and people with eczema especially."},"where":{"summary":"Shins, hands, heels, lips, face."},"how":{"summary":"Lukewarm (not hot) baths, gentle cleanser, thicker moisturiser on damp skin, petrolatum for lips and heels."}}'::jsonb, '{"skinConcerns":["dryness"],"skinTypes":["dry","sensitive"],"climates":["cold","hot_dry"]}'::jsonb, 'published', '2026-10-01');
