insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('hair-oiling', 'Hair oiling (champi)', 'ayurvedic', 'practices', 'Applying oil to the scalp and hair before washing, often with massage. A long-standing Indian tradition.', array['champi', 'oil massage', 'head massage', 'hair oil', 'oiling hair', 'shiro abhyanga', 'oil hair']::text[], 'Nourishing hair, calming the mind and maintaining scalp health (shiro abhyanga).', 'reasonable', '[{"claim":"Pre-wash coconut oil can reduce protein loss and breakage","level":"moderate"},{"claim":"Scalp massage feels relaxing","level":"traditional"},{"claim":"Oiling makes hair grow faster or thicker","level":"insufficient"},{"claim":"Oiling cures dandruff","level":"unsupported"}]'::jsonb, '{"risks":["May worsen dandruff or seborrhoeic dermatitis in some people","Can trigger forehead acne","Hot oil can burn"],"hygiene":["Use clean containers; do not reuse oil left over in a warmed bowl"],"precautions":["Skip oiling on an inflamed, flaky scalp until dandruff is controlled"]}'::jsonb, '{"what":{"summary":"Applying oil (coconut, sesame, mustard or blends) to scalp and hair."},"why":{"summary":"Traditionally to nourish hair; evidence supports reduced breakage with pre-wash oiling."},"when":{"summary":"30 minutes to a few hours before washing."},"who":{"summary":"Dry, curly, coily or damaged hair.","points":["Caution: dandruff-prone or acne-prone hairline"]},"where":{"summary":"Lengths and ends; scalp if tolerated."},"how":{"summary":"Warm slightly, massage gently, wash out with shampoo.","points":["Common mistake: pulling hair into tight braids after oiling","Common mistake: leaving oil on for days"]}}'::jsonb, '{"hairConcerns":["breakage","frizz"],"scalp":["dry_scalp"]}'::jsonb, 'published', '2026-10-03');
