insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('oil-pulling', 'Oil pulling (gandusha / kavala)', 'ayurvedic', 'practices', 'Swishing a spoonful of oil (often sesame or coconut) in the mouth for several minutes. A traditional Ayurvedic oral-care practice.', array['gandusha', 'kavala', 'oil swishing', 'coconut oil pulling', 'sesame oil pulling']::text[], 'Oral cleanliness and gum health.', 'use_with_caution', '[{"claim":"May modestly reduce plaque and bad breath","level":"preliminary","note":"Small, short studies of variable quality."},{"claim":"Replaces brushing with fluoride toothpaste","level":"unsupported"},{"claim":"\"Detoxifies\" the body","level":"unsupported"}]'::jsonb, '{"risks":["Accidental inhalation of oil (lipoid pneumonia) has been reported, particularly in children","Upset stomach if swallowed"],"hygiene":["Spit oil into the bin, not the sink (it can block drains)"],"precautions":["Not for young children","Do not use instead of brushing or dental care"],"seeProfessional":["Bleeding gums, persistent bad breath or tooth pain"]}'::jsonb, '{"what":{"summary":"Swishing oil in the mouth for 5–20 minutes, then spitting."},"why":{"summary":"Traditionally for oral hygiene; evidence is preliminary."},"when":{"summary":"Optional, in addition to brushing twice daily."},"who":{"summary":"Adults who want to try it alongside regular care.","points":["Not for young children"]},"where":{"summary":"Mouth only — do not swallow."},"how":{"summary":"Swish gently, spit into the bin, rinse, then brush with fluoride toothpaste."}}'::jsonb, '{"oralConcerns":["bad_breath","gum_care"],"cautionFor":["children"]}'::jsonb, 'published', '2026-09-29');
