insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('neem-datun', 'Neem chewing stick (datun)', 'ayurvedic', 'practices', 'Chewing the end of a neem twig into a brush and using it to clean teeth. Still used in parts of India.', array['datun', 'datoon', 'neem twig', 'chewing stick', 'miswak', 'dantan']::text[], 'Cleaning teeth and freshening breath.', 'use_with_caution', '[{"claim":"Mechanically cleans teeth when used properly","level":"moderate"},{"claim":"Provides cavity protection equal to fluoride toothpaste","level":"unsupported"}]'::jsonb, '{"risks":["Can injure gums if used roughly","No fluoride, so less cavity protection"],"hygiene":["Use a fresh, clean twig; trim the used end daily"]}'::jsonb, '{"what":{"summary":"A neem twig chewed into bristles and used as a toothbrush."},"why":{"summary":"Traditional, low-cost oral cleaning."},"when":{"summary":"Daily if preferred — ideally alongside fluoride toothpaste use."},"who":{"summary":"Adults who prefer it.","points":["Children: fluoride toothpaste is preferred"]},"where":{"summary":"Teeth (gently along the gum line)."},"how":{"summary":"Chew the end until soft and fibrous; brush gently; discard after a few days."}}'::jsonb, '{}'::jsonb, 'published', '2026-09-29');
