insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('ubtan', 'Ubtan (traditional face & body pack)', 'ayurvedic', 'practices', 'A paste of gram flour (besan), turmeric and other ingredients, traditionally used to cleanse and polish the skin, including in pre-wedding rituals.', array['ubtan', 'besan pack', 'haldi pack', 'besan haldi', 'gram flour face pack', 'haldi ceremony']::text[], 'Cleansing, gentle exfoliation and "glow".', 'use_with_caution', '[{"claim":"Gram flour paste gently removes oil and dead skin when rubbed off","level":"traditional"},{"claim":"Ubtan permanently lightens skin","level":"unsupported"}]'::jsonb, '{"risks":["Irritation or allergy to turmeric or added ingredients","Over-scrubbing causes irritation","Yellow staining"],"hygiene":["Mix fresh each time; do not store wet pastes","Use clean, good-quality ingredients"],"precautions":["Avoid adding lemon juice","Do not use on broken or acne-inflamed skin","Patch test"]}'::jsonb, '{"what":{"summary":"A traditional paste of besan, turmeric and milk, curd or rose water."},"why":{"summary":"Traditionally for cleansing and glow; evidence is mostly traditional."},"when":{"summary":"Occasionally (e.g. once a week), not daily."},"who":{"summary":"People without allergies to the ingredients.","points":["Caution: sensitive or acne-inflamed skin"]},"where":{"summary":"Face and body (intact skin)."},"how":{"summary":"Apply a thin layer, let it partially dry, rinse with water while rubbing very gently.","points":["Common mistake: scrubbing hard","Common mistake: adding lemon"]}}'::jsonb, '{}'::jsonb, 'published', '2026-09-27');
