insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('multani-mitti-pack', 'Multani mitti face pack', 'home_remedy', 'kitchen', 'Fuller''s earth clay mixed with water or rose water and applied as a mask to absorb oil.', array['multani mitti', 'fullers earth pack', 'clay mask', 'mud pack']::text[], null, 'reasonable', '[{"claim":"Absorbs surface oil temporarily","level":"moderate","note":"Clays are absorbent; effects are short-lived."},{"claim":"Treats acne","level":"insufficient"}]'::jsonb, '{"risks":["Dryness and tightness","Loose clay may be contaminated"],"hygiene":["Buy sealed, cosmetic-grade clay","Mix fresh each time"],"precautions":["Rinse before it cracks fully","Skip on dry or sensitive skin"]}'::jsonb, '{"what":{"summary":"An absorbent clay face pack."},"why":{"summary":"To reduce oiliness temporarily."},"when":{"summary":"Once a week or less."},"who":{"summary":"Oily skin.","points":["Not ideal for dry or sensitive skin"]},"where":{"summary":"Oily areas such as the T-zone."},"how":{"summary":"Thin layer, 5–10 minutes, rinse with lukewarm water, moisturise."}}'::jsonb, '{"skinTypes":["oily"],"climates":["hot_humid"]}'::jsonb, 'published', '2026-09-25');
