insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('lemon-on-skin', 'Lemon juice on the skin', 'home_remedy', 'avoid', 'A popular remedy for tan and dark spots. Lemon juice is highly acidic and can cause irritation, and when skin is exposed to sun it can cause burns and dark patches (phytophotodermatitis).', array['lemon', 'nimbu', 'lemon juice', 'lemon for tan', 'lemon for dark spots', 'de-tan']::text[], null, 'not_recommended', '[{"claim":"Lemon lightens dark spots","level":"unsupported"},{"claim":"Lemon on skin plus sun can cause burns and dark patches","level":"established"}]'::jsonb, '{"risks":["Irritation and chemical burns","Phytophotodermatitis (burns or dark patches after sun exposure)","Worsening pigmentation"],"precautions":["Do not apply undiluted citrus juice to skin","Wash off any citrus contact before going in the sun"],"seeProfessional":["Blistering, burning or dark streaks after contact with citrus"]}'::jsonb, '{"what":{"summary":"Applying fresh lemon juice to the skin."},"why":{"summary":"Popularly used for tan and dark spots — but evidence does not support it and risks are real."},"when":{"summary":"Not recommended."},"who":{"summary":"Not recommended for anyone, especially those with sensitive or pigmentation-prone skin."},"where":{"summary":"Not recommended on skin."},"how":{"summary":"Choose sunscreen and evidence-based tone-evening ingredients instead."}}'::jsonb, '{}'::jsonb, 'published', '2026-10-06');
