insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('toothpaste-on-pimples', 'Toothpaste on pimples', 'home_remedy', 'avoid', 'A widely shared hack. Toothpaste is not made for skin; ingredients like SLS, menthol and fluoride can irritate and burn.', array['toothpaste pimple', 'toothpaste acne', 'toothpaste on face']::text[], null, 'not_recommended', '[{"claim":"Toothpaste dries out pimples","level":"unsupported"}]'::jsonb, '{"risks":["Irritation, burning, dark marks"]}'::jsonb, '{"what":{"summary":"Dabbing toothpaste on pimples overnight."},"why":{"summary":"Believed to dry spots; not supported, and can irritate."},"when":{"summary":"Not recommended."},"who":{"summary":"Not recommended for anyone."},"where":{"summary":"Not recommended on skin."},"how":{"summary":"Use a spot treatment made for skin (e.g. benzoyl peroxide or salicylic acid) or a hydrocolloid patch."}}'::jsonb, '{}'::jsonb, 'published', '2026-10-06');
