insert into care_topics (id, name, kind, subcategory_id, summary, synonyms, traditional_purpose, recommendation, claims, details, five_w, suitability, status, last_reviewed) values ('onion-juice-hair', 'Onion juice for hair fall', 'home_remedy', 'kitchen', 'Applying onion juice to the scalp. Popular online; evidence is limited to very small studies.', array['onion juice', 'onion oil', 'pyaaz', 'onion for hair']::text[], null, 'use_with_caution', '[{"claim":"Onion juice regrows hair","level":"preliminary","note":"Small early studies, mainly in patchy hair loss; not established."}]'::jsonb, '{"risks":["Scalp irritation and itching","Strong odour"],"hygiene":["Prepare fresh; do not store"],"precautions":["Patch test","Patchy or sudden hair loss needs medical assessment"],"seeProfessional":["Round bald patches","Rapid shedding"]}'::jsonb, '{"what":{"summary":"Fresh onion juice applied to the scalp."},"why":{"summary":"Hoped to reduce hair fall; evidence is preliminary."},"when":{"summary":"If tried at all, occasionally and briefly."},"who":{"summary":"Adults without scalp irritation, after a patch test."},"where":{"summary":"Scalp, avoiding eyes."},"how":{"summary":"Short contact, then wash; stop if itching or redness."}}'::jsonb, '{}'::jsonb, 'needs_verification', '2026-09-25');
