insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('simple-skincare-routine-indian-climate', 'How to Build a Simple Skincare Routine for Indian Climate', 'beginner_guide', 'Indian weather can be tough on your skin — from hot summers to humid monsoons. A simple cleanse–moisturise–protect routine works for most people.', array['Keep it simple: cleanse, moisturise, protect', 'Choose lighter textures in humid months and richer ones in dry winters', 'Add one targeted active at a time, only if you need it']::text[], '[{"heading":"Start with three steps","body":["Most people need only a gentle cleanser, a moisturiser suited to their skin and the season, and a broad-spectrum sunscreen in the morning."],"bullets":["Cleanse: once or twice daily, gently","Moisturise: gel in humid weather, cream in dry weather","Protect: sunscreen every morning, reapplied outdoors"]},{"heading":"Adjust for the season, not for trends","body":["In the humid pre-monsoon and monsoon months many people prefer gel moisturisers and lighter sunscreens. In north Indian winters, richer creams and lukewarm baths help prevent dryness."]},{"heading":"Adding actives","body":["If you have a specific goal — acne, uneven tone — add one evidence-backed active, give it 8–12 weeks, and patch test first. Stacking many actives is a common cause of irritation."]}]'::jsonb, array['routine', 'skincare routine', 'beginner', 'indian weather', 'humid', 'climate', 'basic skincare']::text[], 6, 'CareLens editorial team', '2026-04-12', '2026-10-12', 'published');
