insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('reading-ingredient-labels', 'Reading an Ingredient Label: What the Order Does (and Doesn''t) Tell You', 'label_literacy', 'Ingredient lists are usually in descending order of amount, but that only tells you so much.', array['Ingredients above 1% are generally listed in descending order', 'Below about 1%, order can be arbitrary', 'A low position does not mean an ingredient is ineffective — some work at small amounts', 'Labels rarely tell you concentrations unless the brand chooses to']::text[], '[{"heading":"Descending order — with a catch","body":["In many markets, ingredients are listed in descending order of weight for those present above 1%. Ingredients at or below 1% may be listed in any order. Colourants are often listed at the end."]},{"heading":"INCI names","body":["INCI (International Nomenclature of Cosmetic Ingredients) names can look intimidating: \"Aqua\" is water, \"Butyrospermum Parkii Butter\" is shea butter, \"Cocos Nucifera Oil\" is coconut oil."]},{"heading":"What you cannot conclude","body":["You cannot work out exact percentages, how well the formula delivers an ingredient, or whether a product suits you from the list alone. Use the list to spot ingredients you know you react to and to compare similar products."]},{"heading":"Indian labels","body":["Cosmetics sold in India must carry an ingredient list, net quantity, manufacturer details and batch information under the Cosmetics Rules. Check the CDSCO and BIS websites for current requirements."]}]'::jsonb, array['ingredient list', 'label', 'inci', 'ingredient order', 'how to read labels', 'percentage']::text[], 5, 'CareLens editorial team', '2026-05-02', '2026-10-10', 'published');
