insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('skincare-myths', 'Seven Common Personal-Care Myths', 'myths', 'From "natural is always safe" to "dark skin doesn''t need sunscreen" — what the evidence actually says.', array['Natural is not automatically safer', 'Everyone benefits from sun protection', 'Oils do not stop hair fall from the root', 'Fluoride toothpaste is the best-established way to prevent cavities']::text[], '[{"heading":"Myths and facts","body":["Each of these comes up often in Indian households and social media."],"bullets":["Myth: Natural products are always safe. Fact: Plants can cause allergies and contamination; dose and preparation matter.","Myth: Darker skin doesn''t need sunscreen. Fact: It still tans and develops pigmentation and UV damage.","Myth: Hair oil stops hair fall. Fact: Oils may reduce breakage but do not treat shedding from the root.","Myth: Toothpaste dries pimples. Fact: It irritates skin.","Myth: Lemon lightens dark spots. Fact: It can burn and darken skin in the sun.","Myth: Higher percentages are always better. Fact: Many actives work at lower strengths with less irritation.","Myth: Herbal toothpaste without fluoride protects equally. Fact: Fluoride has the strongest anti-cavity evidence."]}]'::jsonb, array['myths', 'myth', 'facts', 'natural', 'misconceptions']::text[], 4, 'CareLens editorial team', '2026-06-01', '2026-10-06', 'published');
