insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('price-per-ml-value', 'Is It Worth the Price? Cost Versus Value', 'value', 'Price per ml or gram makes comparisons fairer — but value also depends on what is in the bottle and whether you need it.', array['Compare price per 100 ml/g, not pack price', 'Higher price does not mean a higher concentration or better formula', 'You only get value from products you actually need and use correctly']::text[], '[{"heading":"Price per unit","body":["A ₹599 serum in 30 ml costs about ₹20 per ml. A ₹750 serum in 30 ml costs about ₹25 per ml. Always check the net quantity."]},{"heading":"Price is not evidence","body":["Packaging, branding and distribution drive much of a product''s price. A well-formulated inexpensive moisturiser may serve you as well as an expensive one."]},{"heading":"Questions to ask","body":[],"bullets":["Does it contain an ingredient with good evidence for my goal?","Is the strength declared?","How long will a pack last at the recommended amount?","Do I already own something that does the same job?"]}]'::jsonb, array['price', 'worth', 'value', 'expensive', 'budget', 'cheap', 'cost', 'price per ml']::text[], 4, 'CareLens editorial team', '2026-06-18', '2026-10-05', 'published');
