insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('understanding-evidence', 'How to Read Evidence: Established, Preliminary and Traditional', 'evidence', 'CareLens labels every claim with an evidence level. Here is what each means and why it matters.', array['Established: consistent evidence from regulators, guidelines or multiple good trials', 'Moderate: supportive studies with gaps', 'Preliminary: small, lab or early studies', 'Traditional: long use, not established by controlled research', 'Unsupported: evidence contradicts it, or it carries clear risk']::text[], '[{"heading":"Why levels matter","body":["A lab study showing an extract kills bacteria in a dish is very different from a trial showing a product clears acne in people. Both may be described as \"proven\" in marketing."]},{"heading":"Traditional is not the same as unproven or proven","body":["Traditional use tells us what people have valued for generations. It is useful context but does not, on its own, show effectiveness or safety for a specific product."]},{"heading":"What CareLens does not do","body":["We do not create scores, rankings or \"best product\" lists without a defensible basis. When evidence is missing, we say so."]}]'::jsonb, array['evidence', 'research', 'studies', 'science', 'proven', 'clinical trial', 'how we rate']::text[], 5, 'CareLens editorial team', '2026-03-15', '2026-10-01', 'published');
