insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('fluoride-toothpaste-guide', 'Choosing a Toothpaste: Fluoride, Sensitivity and Herbal Options', 'ingredient_explainer', 'What to look for on a toothpaste label, including fluoride content and sensitivity actives.', array['Look for fluoride and its ppm on the label', 'Sensitivity pastes (potassium nitrate, stannous fluoride) take weeks', 'Herbal pastes vary — many contain fluoride, some do not', 'Children need age-appropriate amounts']::text[], '[{"heading":"Fluoride first","body":["Fluoride has the strongest evidence for preventing cavities. Indian toothpaste packs state fluoride content in ppm. Many international guidelines refer to about 1000–1500 ppm for adults."]},{"heading":"For sensitive teeth","body":["Toothpastes with potassium nitrate or stannous fluoride can reduce sensitivity with twice-daily use over 2–4 weeks. Persistent pain needs a dentist."]},{"heading":"Herbal toothpastes","body":["If you prefer a herbal paste, check whether it contains fluoride. Neem and clove have a long tradition but are not shown to replace fluoride for cavity prevention."]},{"heading":"Children","body":["Use a smear (rice-grain size) under 3 years and a pea-sized amount from 3–6 years, and supervise brushing. Some regions of India have high natural fluoride in water; a dentist can advise."]}]'::jsonb, array['toothpaste', 'fluoride', 'sensitive teeth', 'herbal toothpaste', 'which toothpaste']::text[], 5, 'CareLens editorial team', '2026-07-04', '2026-10-05', 'published');
