insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('common-product-mistakes', 'Common Product-Use Mistakes (and Easy Fixes)', 'mistakes', 'Most product disappointments come from how products are used, not what is in them.', array['Use enough sunscreen and reapply', 'Leave anti-dandruff shampoo on the scalp for a few minutes', 'Don''t rinse fluoride off immediately', 'Introduce one new active at a time']::text[], '[{"heading":"Skin","body":[],"bullets":["Too little sunscreen — use about two finger-lengths for face and neck","Starting several actives together","Judging results after a week"]},{"heading":"Hair","body":[],"bullets":["Rinsing anti-dandruff shampoo immediately","Leaving heavy oil on a flaky scalp for days","Tight hairstyles on wet hair"]},{"heading":"Oral care","body":[],"bullets":["Brushing hard with a hard brush","Rinsing heavily after brushing","Using mouthwash instead of brushing"]}]'::jsonb, array['mistakes', 'how to use', 'wrong', 'tips']::text[], 3, 'CareLens editorial team', '2026-07-22', '2026-10-03', 'published');
