insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('natural-vs-synthetic', 'Are Ayurvedic and Natural Alternatives Effective?', 'safety', 'Traditional ingredients can be part of good care. Here is how to weigh them fairly — without assuming they are better or worse.', array['Judge each ingredient on its own evidence', 'Traditional use is context, not proof', 'Natural products can cause allergies and may be contaminated', 'Do not delay medical care for a remedy']::text[], '[{"heading":"A fair comparison","body":["Some traditional ingredients, such as coconut oil for hair breakage, have reasonable supporting evidence. Others, like neem or amla, have mainly laboratory or traditional support. A few popular remedies, such as lemon on skin, carry real risks."]},{"heading":"Regulation","body":["Ayurvedic products in India are regulated under the Drugs and Cosmetics Act with oversight from the Ministry of AYUSH. Check for licence details on the label."]},{"heading":"Safety basics","body":[],"bullets":["Patch test","Use clean, fresh preparations","Keep oils (especially neem oil) away from children","See a doctor for worsening, painful or spreading symptoms"]}]'::jsonb, array['ayurveda', 'ayurvedic', 'natural', 'herbal', 'alternatives', 'traditional', 'effective']::text[], 5, 'CareLens editorial team', '2026-08-10', '2026-10-02', 'published');
