insert into articles (id, title, type, summary, takeaways, sections, keywords, read_minutes, author, published_on, last_reviewed, status) values ('faq-basics', 'Personal Care FAQ: Quick Answers', 'faq', 'Short answers to questions people ask most, each linked to deeper explanations.', array['Short answers, with links to full 5W1H explanations']::text[], '[{"heading":"Do I need a toner?","body":["Not necessarily. Toners are optional; some contain useful ingredients, others are mostly water and fragrance."]},{"heading":"What does PA+++ mean?","body":["PA is a UVA protection rating used in Asian markets. More plus signs indicate higher UVA protection."]},{"heading":"How often should I wash my hair in summer?","body":["As often as you need to feel comfortable — daily washing with a mild shampoo is fine for most people in hot, humid weather."]},{"heading":"Is mouthwash necessary?","body":["No. Brushing twice daily with fluoride toothpaste and cleaning between teeth matter most."]}]'::jsonb, array['faq', 'questions', 'toner', 'pa+++', 'mouthwash', 'wash hair']::text[], 3, 'CareLens editorial team', '2026-08-28', '2026-10-01', 'published');
